  if (d.say) extra.push(`<div>Says: <span class="quote">${esc(d.say)}</span></div>`);
  return `<li${latest ? ' class="latest"' : ""}><div class="when">tick ${d.t}, ${esc(TRIGGER_WORDS[d.trigger] || d.trigger || "")}</div>
